
#[cfg(test)]mod mass69_controller_development_tests {
    use super::*;
    fn ready()->LoginController {let mut c=LoginController::default();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();c.state.world.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}c.state.phase=LoginPhase::WorldReady;c.state.game_connected=true;c.state.selected_source=Some("isolated".into());c.state.selected_character=Some("fixture".into());c.state.inventory.owner=Some(super::super::native_inventory::Owner{connection:c.transport.snapshot().epoch,selection:1,character:"fixture".into()});c.state.world.hp=Some([1,100]);c.state.world.mp=Some([1,100]);c.state.world.learned_skills.clear();c}
    fn summon(c:&LoginController)->Vec<u8>{let mut b=vec![85,0,64];b.extend(c.state.world.own_actor().unwrap().id.to_le_bytes());b}
    #[test]fn controller_routes_recipient_question_without_local_skill_or_mp_and_retirement_revokes(){let mut c=ready();c.state.world.mp=Some([0,100]);c.accept_game(&[36,236,2,0]).unwrap();let token=c.mass_prompt().unwrap().token();assert!(c.ensure_native_input().is_err());c.interrupt_world_actions();assert!(c.mass_prompt().is_none());assert!(c.answer_mass(&token,true).is_err());}
    #[test]fn S30_records_enter_owned_menu_and_new_bookmark_invalidates_old_choice(){let mut c=ready();c.state.world.learned_skills.insert(69);let mut menu=super::super::native_mass69::Menu::default();c.sync_mass_menu(&mut menu,true).unwrap();let id=menu.command_id().unwrap();let first=c.mass_choice(&menu,id,0).unwrap();assert!(c.mass_choice_current(&first));let mut b=vec![48];b.extend(b"town\0");b.extend(123_u16.to_le_bytes());b.extend(234_u16.to_le_bytes());b.extend(4_u16.to_le_bytes());c.accept_game(&b).unwrap();assert!(c.mass_choice(&menu,id,0).is_err());c.sync_mass_menu(&mut menu,true).unwrap();let choice=c.mass_choice(&menu,menu.command_id().unwrap(),1).unwrap();assert!(c.mass_choice_current(&choice));assert_eq!(super::super::native_skills::mass_request(&c.state,c.transport.snapshot().epoch,&c.mass_books,&choice).unwrap(),vec![20,8,4,4,0,123,0,234,0]);}
    #[test]fn own_native_summon_grant_blocks_world_input_and_one_cross_map_enters_WORLD_rebuild(){let mut c=ready();let epoch=c.transport.snapshot().epoch;let body=summon(&c);c.mass_portal.receive(&c.state,epoch,&body).unwrap();assert!(c.mass_travel_pending());assert!(c.ensure_native_input().is_err());let hp=c.state.world.hp;c.admit_received_portal(super::super::native_portal::Destination{map:4,x:123,y:234}).unwrap();assert_eq!(c.state.phase,LoginPhase::WorldEntering);assert!(!c.mass_travel_pending());assert_eq!(c.state.world.hp,hp);assert!(c.admit_received_portal(super::super::native_portal::Destination{map:4,x:123,y:234}).is_err());}
    #[test]fn stale_summon_grant_rejects_before_fallback_or_scene_mutation(){let mut c=ready();let epoch=c.transport.snapshot().epoch;let body=summon(&c);c.mass_portal.receive(&c.state,epoch,&body).unwrap();let id=c.state.world.own_actor().unwrap().id;c.state.world.actors.get_mut(&id).unwrap().incarnation+=1;let before=serde_json::to_value(&c.state.world).unwrap();assert!(c.admit_received_portal(super::super::native_portal::Destination{map:4,x:123,y:234}).is_err());assert_eq!(c.state.phase,LoginPhase::WorldReady);assert_eq!(serde_json::to_value(&c.state.world).unwrap(),before);}
    #[test]fn ordinary_world_cross_map_without_a_grant_is_rejected_and_malformed_ask_is_atomic(){let mut c=ready();assert!(c.admit_received_portal(super::super::native_portal::Destination{map:4,x:123,y:234}).is_err());c.accept_game(&[36,236,2,0]).unwrap();let t=c.mass_prompt().unwrap().token();assert!(c.accept_game(&[36,236,2]).is_err());assert_eq!(c.mass_prompt().unwrap().token(),t);}
}
